                        if st.out_range().beg_idx != beg || st.out_range().count != nb { range_ok = false; }
                        range_legs += 1; range_sites |= 16;
                        if st.advance().is_err() { range_ok = false; }
                        if st.out_range().beg_idx != beg || st.out_range().count != nb + 1 { range_ok = false; }
