    if svN > 256 { svN = 256; }
    let svK = match u32::try_from(params["unstablePeriod"].as_i64().unwrap_or(0)) {
        Ok(v) => v,
        Err(_) => return "{\"error\":\"negative unstablePeriod\"}".to_string(),
    };
    let mut fz_o = vec![0.0f64; svN];
