                    for t in p..mid { if sa.update(fz_o[t], fz_h[t], fz_l[t], fz_c[t]).is_err() { all_ok = false; forked = false; if diag.is_empty() { diag = format!(",\"copyPreRejected\":{}", t); } break; } }
                    let mut sb = sa.clone();
