                        if let Ok(pk) = pk_res {
                            if pk != up { peek_all = false; }
                        }
                        if up != b0[t - beg] { all_ok = false; if diag.is_empty() { diag = format!(",\"badBar\":{},\"badOut\":0,\"batchv\":\"{}\",\"streamv\":\"{}\"", t, b0[t - beg], up); } }
