        let rc = match c2.mama(0, svN - 1, &fz_c, optInFastLimit, optInSlowLimit, &mut b0, Some(&mut b1)) { Ok(r) => { beg = r.beg_idx; nb = r.count; RetCode::Success } Err(e) => { beg = 0; nb = 0; e } };
