        let rc = match c2.minindex(0, svN - 1, &fz_c, optInTimePeriod, &mut b0) { Ok(r) => { beg = r.beg_idx; nb = r.count; RetCode::Success } Err(e) => { beg = 0; nb = 0; e } };
        let lb = c2.minindex_lookback(optInTimePeriod).unwrap_or(usize::MAX);
