            let mut fb1 = vec![0.0f64; m];
            let mut fb2 = vec![0.0f64; m];
            r.rc_fill = match core.donchian_open_and_fill(&inHigh[..m], &inLow[..m], optInTimePeriod, &mut fb0, &mut fb1, &mut fb2) { Ok(_) => 0, Err(e) => retcode_to_int(e) };
