            if cmp && sv_xtier_ne(rb2[lb - beg], u.2, &mut r.benign) { cmp = false; r.out = 2; r.batch = rb2[lb - beg].to_bits(); r.stream = u.2.to_bits(); }
            if cmp { r.open_bars += 1; }
